INSERT INTO repo_cf_skills (cf_skill_id, education_level, sub_heading, text, status) VALUES ('CFS_SDG05_TER_019', 'Tertiary education', 'Leadership and gender equality in institutions', 'Emphasise the role of individuals in contributing to a more equitable and inclusive society through advocacy, education and direct action.', 'Active'), ('CFS_SDG05_TER_020', 'Tertiary education', 'Data, policy and programme evaluation', 'Use gender-responsive data collection methods and analysis to ensure gender-disaggregated data inform decisions and strategies.', 'Active'), ('CFS_SDG05_TER_021', 'Tertiary education', 'Data, policy and programme evaluation', 'Monitor and evaluate gender equality programmes to identify successes, barriers and opportunities for further learning and development.', 'Active'), ('CFS_SDG05_TER_022', 'Tertiary education', 'Data, policy and programme evaluation', 'Critically analyse societal norms, gender stereotypes and discriminatory laws, and assess how these impact women’s education and career prospects.', 'Active'), ('CFS_SDG05_TER_023', 'Tertiary education', 'Data, policy and programme evaluation', 'Scrutinise financial allocations to gender equality programmes, ensuring that resources are spent equitably and align with gender-responsive goals.', 'Active'), ('CFS_SDG05_TER_024', 'Tertiary education', 'Data, policy and programme evaluation', 'Track public spending and assess its impact on gender equality, ensuring resource allocation aligns with gender-responsive goals.', 'Active'), ('CFS_SDG05_ADULT_001', 'Adult education', 'Analytical and policy skills', 'Use gender analysis tools (for example, the 24-hour time chart) to evaluate the impact of laws, policies and programmes on men and women.', 'Active'), ('CFS_SDG05_ADULT_002', 'Adult education', 'Analytical and policy skills', 'Apply gender mainstreaming strategies to policy development and adult education programmes to promote gender-equitable service delivery.', 'Active'), ('CFS_SDG05_ADULT_003', 'Adult education', 'Analytical and policy skills', 'Conduct gender audits and integrate intersectional perspectives into programme design and evaluation.', 'Active'), ('CFS_SDG05_ADULT_004', 'Adult education', 'Analytical and policy skills', 'Track the progress of gender-focused initiatives and use evidence to inform advocacy and share best practices.', 'Active'), ('CFS_SDG05_ADULT_005', 'Adult education', 'Education, curriculum and advocacy', 'Critically analyse educational content and pedagogical approaches to identify and address gender bias and stereotypes.', 'Active'), ('CFS_SDG05_ADULT_006', 'Adult education', 'Education, curriculum and advocacy', 'Design and advocate for gender-inclusive curricula, learning environments and institutional practices.', 'Active'), ('CFS_SDG05_ADULT_007', 'Adult education', 'Education, curriculum and advocacy', 'Educate adults and communities on women’s rights, including addressing harmful practices such as child marriage, FGM and trafficking.', 'Active'), ('CFS_SDG05_ADULT_008', 'Adult education', 'Education, curriculum and advocacy', 'Develop inclusive SRH education programmes that address reproductive rights, maternal health, contraception, informed consent and prevention of GBV.', 'Active'), ('CFS_SDG05_ADULT_009', 'Adult education', 'Education, curriculum and advocacy', 'Create and assess school-and community-based interventions to prevent and respond to gender-based violence.', 'Active'), ('CFS_SDG05_ADULT_010', 'Adult education', 'Community-based solutions and empowerment', 'Develop strategies that promote women’s equal access to land, water, ICT and other critical resources.', 'Active'), ('CFS_SDG05_ADULT_011', 'Adult education', 'Community-based solutions and empowerment', 'Design community-based solutions to address gender inequalities in the informal economy and natural resource management.', 'Active'), ('CFS_SDG05_ADULT_012', 'Adult education', 'Community-based solutions and empowerment', 'Establish support systems and leadership pathways for women in marginalised and rural communities.', 'Active'), ('CFS_SDG05_ADULT_013', 'Adult education', 'Community-based solutions and empowerment', 'Promote equitable digital inclusion and expand online learning access for women and girls.', 'Active'), ('CFS_SDG05_ADULT_014', 'Adult education', 'Financial, vocational and digital inclusion', 'Integrate gender-sensitive financial literacy and micro-finance strategies to promote women’s independence and community health.', 'Active'), ('CFS_SDG05_ADULT_015', 'Adult education', 'Financial, vocational and digital inclusion', 'Support gender-responsive vocational education in non-traditional sectors such as STEM and technology.', 'Active'), ('CFS_SDG05_ADULT_016', 'Adult education', 'Financial, vocational and digital inclusion', 'Advocate for policies that ensure equitable digital infrastructure and access.', 'Active'), ('CFS_SDG05_ADULT_017', 'Adult education', 'Financial, vocational and digital inclusion', 'Develop sustainable strategies to implement gender equality initiatives with measurable, inclusive outcomes.', 'Active'), ('CFS_SDG05_ADULT_018', 'Adult education', 'Leadership and campaign development', 'Promote inclusive leadership practices and gender-equitable governance structures.', 'Active'), ('CFS_SDG05_ADULT_019', 'Adult education', 'Leadership and campaign development', 'Create peer education, awareness campaigns and digital media content to advance gender equality.', 'Active'), ('CFS_SDG05_ADULT_020', 'Adult education', 'Leadership and campaign development', 'Collaborate across disciplines and sectors to address root causes of inequality.', 'Active'), ('CFS_SDG05_ADULT_021', 'Adult education', 'Leadership and campaign development', 'Use digital platforms to amplify marginalised voices and drive advocacy for systemic change.', 'Active'), ('CFS_SDG06_SEC_001', 'Secondary education', 'Personal and community water footprints:', 'Calculate and interpret the water footprint of personal and community activities (for example, food consumption, water use at home).', 'Active'), ('CFS_SDG06_SEC_002', 'Secondary education', 'Personal and community water footprints:', 'Compare local water footprints with global averages, gaining a deeper understanding of the global disparities in water use.', 'Active'), ('CFS_SDG06_SEC_003', 'Secondary education', 'Personal and community water footprints:', 'Create informative posters illustrating the water footprint of common products (for example, cotton, meat, electronics), focusing on green, blue and grey water footprints.', 'Active'), ('CFS_SDG06_SEC_004', 'Secondary education', 'Personal and community water footprints:', 'Use the posters to raise awareness about how consumer choices affect global water resources.', 'Active'), ('CFS_SDG06_SEC_005', 'Secondary education', 'Evaluate water use', 'Analyse consumption patterns of water in domestic, industrial and agricultural settings.', 'Active'), ('CFS_SDG06_SEC_006', 'Secondary education', 'Evaluate water use', 'Analyse trends and how consumption patterns correlate with local water availability and global sustainability goals.', 'Active'), ('CFS_SDG06_SEC_007', 'Secondary education', 'Policy analysis', 'Use integrated thinking to analyse and evaluate water policies and infrastructure challenges, and how social, environmental and economic factors influence water management.', 'Active'), ('CFS_SDG06_SEC_008', 'Secondary education', 'Policy analysis', 'Suggest changes or improvements to existing water policies based on integrated analysis.', 'Active'), ('CFS_SDG06_SEC_009', 'Secondary education', 'Climate change adaptation', 'Adjust water use practices when facing challenges like water shortages or changes in the hydrologic cycle due to climate change.', 'Active'), ('CFS_SDG06_SEC_010', 'Secondary education', 'Climate change adaptation', 'Apply strategies to build resilience against water supply disruptions.', 'Active'), ('CFS_SDG06_SEC_011', 'Secondary education', 'Evaluate water issues locally and globally', 'Cultivate the ability to analyse water challenges from both local and global perspectives, understanding the interconnectedness of water systems.', 'Active'), ('CFS_SDG06_SEC_012', 'Secondary education', 'Evaluate water issues locally and globally', 'Use digital tools, such as mobile apps and online platforms, to collect, analyse and interpret water-related data for understanding and promoting evidence-based solutions to local water challenges.', 'Active'), ('CFS_SDG06_SEC_013', 'Secondary education', 'Evaluate water issues locally and globally', 'Use locally appropriate tools – such as paper-based surveys, basic mobile phones or community mapping – to gather and interpret information about water use, access and challenges, and explore how simple data can support local water solutions.', 'Active'), ('CFS_SDG06_SEC_014', 'Secondary education', 'Evaluate water issues locally and globally', 'Global water management: explore the challenges and solutions to water access in different countries, focusing on issues like water scarcity, pollution and water governance.', 'Active'), ('CFS_SDG06_SEC_015', 'Secondary education', 'Develop critical thinking and problem-solving skills', 'Visit water resource locations: engage in field visits to locations illustrating water resource challenges, equitable distribution and water management strategies, especially under extreme weather events.', 'Active'), ('CFS_SDG06_SEC_016', 'Secondary education', 'Develop critical thinking and problem-solving skills', 'Develop essential problem-solving skills by engaging in critical thinking activities such as role-playing water-related scenarios, simulating water conflicts and proposing solutions.', 'Active'), ('CFS_SDG06_SEC_017', 'Secondary education', 'Install rainwater harvesting systems', 'Learn how to install rainwater harvesting systems, understanding the importance of sustainable water sourcing.', 'Active'), ('CFS_SDG06_SEC_018', 'Secondary education', 'Install rainwater harvesting systems', 'Propose and implement rainwater harvesting systems in schools or communities as part of water conservation efforts.', 'Active'), ('CFS_SDG06_TVET_001', 'TVET', 'Technical and maintenance skills', 'Operate, monitor and maintain water production plants and treatment facilities.', 'Active'), ('CFS_SDG06_TVET_002', 'TVET', 'Technical and maintenance skills', 'Route, lay and repair water and wastewater pipes.', 'Active'), ('CFS_SDG06_TVET_003', 'TVET', 'Technical and maintenance skills', 'Clean and support industrial and public water infrastructure such as tanks, canals and pipelines.', 'Active'), ('CFS_SDG06_TVET_004', 'TVET', 'Technical and maintenance skills', 'Apply digital and field-based tools – such as mobile data collection apps, geographic information system (GIS) software and water quality testing kits – in plumbing, environmental technology and water systems management to assess local water infrastructure, monitor usage and pollution levels, and contribute to the design, maintenance and improvement of sustainable, evidence-based water solutions.', 'Active'), ('CFS_SDG06_TVET_005', 'TVET', 'Diagnostic and monitoring abilities', 'Use diagnostic tools to assess the condition of water systems and identify faults.', 'Active') ON CONFLICT DO NOTHING;